package com.guocheng.mediapocket;
import android.content.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
final class FusionPlaybackSources {
 static JSONObject resolve(Context c,FusionCatalog.Session session,String flag,String value)throws Exception{JSONObject r=FusionCatalog.request(c,session,"player",value,flag,1);if(r.optInt("parse",0)!=0||r.optInt("jx",0)!=0)throw new Exception("此线路需要网页解析，尚未支持");String raw=r.optString("url");if(raw.isEmpty())throw new Exception("线路没有返回播放地址");String url=TvBoxRules.resolve(session.url,raw);JSONObject headers=r.optJSONObject("header");if(headers==null&&r.opt("header") instanceof String)try{headers=new JSONObject(r.optString("header"));}catch(Exception ignored){}if(headers==null)headers=new JSONObject();JSONObject stream=new JSONObject().put("url",url).put("name",session.site.optString("name")+" · "+flag).put("behaviorHints",new JSONObject().put("proxyHeaders",new JSONObject().put("request",headers)));JSONArray subs=new JSONArray();Object rawSubs=r.opt("subt");if(rawSubs==null)rawSubs=r.opt("subtitles");if(rawSubs instanceof String)try{rawSubs=new JSONArray((String)rawSubs);}catch(Exception ignored){}if(rawSubs instanceof JSONArray)for(int i=0;i<Math.min(50,((JSONArray)rawSubs).length());i++){JSONObject s=((JSONArray)rawSubs).optJSONObject(i);if(s==null)continue;String sub=s.optString("url");if(sub.isEmpty())continue;try{String resolved=TvPosterRules.resolve(session.url,sub);JSONObject entry=new JSONObject(s.toString()).put("url",resolved);subs.put(entry);}catch(Exception ignored){}}stream.put("subtitles",subs);return stream;}
 static JSONArray prepare(Context c,FusionCatalog.Session session,JSONObject detail,String episode,String flag,String value)throws Exception{JSONObject primary=null;Exception error=null;try{primary=resolve(c,session,flag,value);}catch(Exception e){error=e;if(!c.getSharedPreferences("data",0).getBoolean("autoSwitch",true))throw e;}JSONArray out=collect(c,session,detail,episode,value,primary);if(out.length()==0)throw error==null?new Exception("没有同集备用线路"):error;JSONArray subtitles=new JSONArray();HashSet<String> subtitleUrls=new HashSet<>();for(int i=0;i<out.length();i++){JSONArray entries=out.getJSONObject(i).optJSONArray("subtitles");for(int n=0;entries!=null&&n<entries.length()&&subtitles.length()<100;n++){JSONObject entry=entries.optJSONObject(n);if(entry!=null&&subtitleUrls.add(entry.optString("url")))subtitles.put(entry);}}out.getJSONObject(0).put("subtitles",subtitles);return out;}
 static JSONArray collect(Context c,FusionCatalog.Session session,JSONObject detail,String episode,String value,JSONObject primary)throws Exception{JSONArray sources=new JSONArray();if(primary!=null)sources.put(primary);List<FusionPlaybackRules.Route> routes=FusionPlaybackRules.alternatives(detail.optString("vod_play_from"),detail.optString("vod_play_url"),episode,value);if(routes.isEmpty())return sources;ExecutorService pool=Executors.newFixedThreadPool(2);CompletionService<JSONObject> jobs=new ExecutorCompletionService<>(pool);ArrayList<Future<JSONObject>> pending=new ArrayList<>();HashSet<String> seen=new HashSet<>();if(primary!=null)seen.add(primary.optString("url"));for(FusionPlaybackRules.Route route:routes)pending.add(jobs.submit(()->resolve(c,session,route.flag,route.value)));long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);try{for(int i=0;i<pending.size();i++){long left=deadline-System.nanoTime();if(left<=0)break;Future<JSONObject> task=jobs.poll(left,TimeUnit.NANOSECONDS);if(task==null)break;try{JSONObject s=task.get();if(seen.add(s.optString("url")))sources.put(s);}catch(ExecutionException ignored){}}}finally{for(Future<?> p:pending)p.cancel(true);pool.shutdownNow();}return sources;}
}
